"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
export function ProductEditor({ product }: { product: { id: string; name: string; price: number; stock: number; status: string } }) { const router = useRouter(); const [error, setError] = useState(""); const [deleting, setDeleting] = useState(false); async function save(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); const r = await fetch(`/api/products/${product.id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: f.get("name"), price: Number(f.get("price")), stock: Number(f.get("stock")), status: f.get("status") }) }); const d = await r.json(); if (!r.ok) return setError(d.error || "Unable to update product."); router.push("/dashboard/vendor/products"); router.refresh(); } async function remove() { if (!window.confirm(`Delete ${product.name}? This cannot be undone.`)) return; setDeleting(true); const r = await fetch(`/api/products/${product.id}`, { method: "DELETE" }); if (!r.ok) { setError("Unable to delete product."); setDeleting(false); return; } router.push("/dashboard/vendor/products"); router.refresh(); } return <form onSubmit={save} className="grid max-w-2xl gap-4 rounded-2xl border bg-white p-6 dark:bg-gray-900"><label>Name<input name="name" defaultValue={product.name} className="mt-1 w-full rounded border p-2" /></label><label>Price<input name="price" type="number" defaultValue={product.price} className="mt-1 w-full rounded border p-2" /></label><label>Stock<input name="stock" type="number" defaultValue={product.stock} className="mt-1 w-full rounded border p-2" /></label><label>Status<select name="status" defaultValue={product.status} className="mt-1 w-full rounded border p-2"><option>ACTIVE</option><option>INACTIVE</option><option>SOLD_OUT</option></select></label>{error && <p className="text-sm text-red-600">{error}</p>}<div className="flex gap-3"><button className="rounded bg-blue-600 px-4 py-2 font-bold text-white">Save changes</button><button type="button" onClick={remove} disabled={deleting} className="rounded border border-red-300 px-4 py-2 font-bold text-red-700">{deleting ? "Deleting..." : "Delete listing"}</button></div></form>; }
